Override('xi.actions.weaponskills.randgrith.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 2.75, 2.75, 2.75 }\n    params.str_wsc = 0.4\n    params.mnd_wsc = 0.4\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    -- Handle status effect\n    local effectId      = xi.effect.EVASION_DOWN\n    local actionElement = xi.element.ICE\n    local power         = 32\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.CLUB,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor(120 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Mystic Boon\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.mystic_boon.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.50, 2.00 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.5\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    player:addMP(damage)\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/dagger.lua"]={["Path"]="modules/era/lua/actions/weaponskills/dagger.lua",["SHA256"]="d4c0b43b8bb728ddd5f562cf447062ab961a0cd74be7bdc378a16d43f5327ea2",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_dagger', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Wasp Sting\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.wasp_sting.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.POISON\n    local actionElement = xi.element.WATER\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.DAGGER,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor((75 + 15 * tp / 1000) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Gust Slash\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.gust_slash.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.00, 2.50 }\n    params.dex_wsc    = 0.2\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.WIND\n    params.skill      = xi.skill.DAGGER\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shadowstitch\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shadowstitch.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.chr_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.BIND\n    local actionElement = xi.element.ICE\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.DAGGER,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor((5 + tp / 200) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Viper Bite\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.viper_bite.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.atkVaries = { 2.00, 2.00, 2.00 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.POISON\n    local actionElement = xi.element.WATER\n    local power         = 3\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.DAGGER,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor((30 + 6 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Cyclone\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.cyclone.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.000, 2.375, 2.875 }\n    params.dex_wsc    = 0.3\n    params.int_wsc    = 0.25\n    params.ele        = xi.element.WIND\n    params.skill      = xi.skill.DAGGER\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Energy Steal\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.energy_steal.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local skill      = player:getSkillLevel(xi.skill.DAGGER)\n    local ftp        = xi.weaponskills.fTP(math.min(tp, 3000), { 1.00, 1.50, 2.00 })\n    local mpRestored = math.floor(math.floor(skill * 0.11) * ftp)\n\n    if target:isUndead() then\n        mpRestored = 0\n    else\n        local maccParams =\n        {\n            magicalElement = xi.element.DARK,\n            skillType      = xi.skill.DAGGER,\n        }\n\n        local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n        mpRestored = math.floor(mpRestored * resistanceRate)\n\n        mpRestored = target:delMP(mpRestored)\n        mpRestored = player:addMP(mpRestored)\n    end\n\n    action:messageID(target:getID(), xi.msg.basic.SKILL_DRAIN_MP)\n    action:param(target:getID(), mpRestored)\n    return 1, 0, false, mpRestored\nend)\n\n-----------------------------------\n-- Energy Drain\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.energy_drain.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local skill      = player:getSkillLevel(xi.skill.DAGGER)\n    local wsc        = math.floor(player:getStat(xi.mod.MND) * 0.25)\n    local ftp        = xi.weaponskills.fTP(math.min(tp, 3000), { 1.25, 1.75, 2.25 })\n    local mpRestored = math.floor((math.floor(skill * 0.11) + wsc) * ftp)\n\n    if target:isUndead() then\n        mpRestored = 0\n    else\n        local maccParams =\n        {\n            magicalElement = xi.element.DARK,\n            skillType      = xi.skill.DAGGER,\n        }\n\n        local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n        mpRestored = math.floor(mpRestored * resistanceRate)\n\n        mpRestored = target:delMP(mpRestored)\n        mpRestored = player:addMP(mpRestored)\n    end\n\n    action:messageID(target:getID(), xi.msg.basic.SKILL_DRAIN_MP)\n    action:param(target:getID(), mpRestored)\n    return 1, 0, false, mpRestored\nend)\n\n-----------------------------------\n-- Dancing Edge\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.dancing_edge.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 5\n    params.ftpMod    = { 1.1875, 1.1875, 1.1875 }\n    params.dex_wsc   = 0.3\n    params.chr_wsc   = 0.4\n    params.accVaries = { 0, 30, 50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shark Bite\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shark_bite.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 2\n    params.ftpMod    = { 2.00, 2.50, 3.00 }\n    params.dex_wsc   = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Evisceration\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.evisceration.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 5\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.dex_wsc    = 0.3\n    params.critVaries = { 0.10, 0.24, 0.48 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Mercy Stroke\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.mercy_stroke.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.str_wsc = 0.6\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Mandalic Stab\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.mandalic_stab.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 2.000, 2.125, 2.500 }\n    params.dex_wsc   = 0.3\n    params.atkVaries = { 1.750, 1.750, 1.750 }\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Mordant Rime\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.mordant_rime.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.dex_wsc = 0.3\n    params.chr_wsc = 0.5\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    -- Handle status effect\n    local effectId      = xi.effect.WEIGHT\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.DAGGER,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(60 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/great_axe.lua"]={["Path"]="modules/era/lua/actions/weaponskills/great_axe.lua",["SHA256"]="9c186887dd4d179d18682e625e49d775fb0138ca025ae609f5c9d403656d4158",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_great_axe', xi.pre(xi.expansion.WOTG))\n\n-- Shield Break\nm:addOverride('xi.actions.weaponskills.shield_break.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.2\n    params.vit_wsc = 0.2\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.EVASION_DOWN\n    local actionElement = xi.element.ICE\n    local power         = 40\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.GREAT_AXE,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor((120 + 6 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-- Iron Tempest\nm:addOverride('xi.actions.weaponskills.iron_tempest.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.str_wsc   = 0.3\n    params.atkVaries = { 1.00, 1.25, 1.50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-- Sturmwind\nm:addOverride('xi.actions.weaponskills.sturmwind.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 2\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.str_wsc   = 0.3\n    params.atkVaries = { 1.00, 1.25, 1.50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-- Armor Break\nm:addOverride('xi.actions.weaponskills.armor_break.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.2\n    params.vit_wsc = 0.2\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.GREAT_AXE,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor((120 + 6 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-- Keen Edge\nm:addOverride('xi.actions.weaponskills.keen_edge.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.35\n    params.critVaries = { 0.50, 0.75, 1.00 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-- Weapon Break\nm:addOverride('xi.actions.weaponskills.weapon_break.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.32\n    params.vit_wsc = 0.32\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ATTACK_DOWN\n    local actionElement = xi.element.WATER\n    local power         = 25\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.GREAT_AXE,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.f