i_hobaku.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.GREAT_KATANA,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(4 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Tachi: Goten\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.tachi_goten.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 0.50, 0.75, 1.00 }\n    params.str_wsc    = 0.3\n    params.hybridWS   = true\n    params.ele        = xi.element.THUNDER\n    params.skill      = xi.skill.GREAT_KATANA\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Tachi: Kagero\n-----------------------------------\nm:addOverride('xi.ac