params.str_wsc    = 0.3\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.ICE\n    params.skill      = xi.skill.GREAT_SWORD\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shockwave\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shockwave.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.SLEEP_I\n    local actionElement = xi.element.DARK\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.GREAT_SWORD,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor((math.randomInt(0, 30) + tp * 0.01) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Crescent Moon\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.crescent_moon.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.75, 2.50 }\n    params.str_wsc = 0.35\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Sickle Moon\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.sickle_moon.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.50, 2.00, 2.75 }\n    params.str_wsc = 0.2\n    params.agi_wsc = 0.2\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Spinning Slash\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.spinning_slash.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 2.50, 3.00, 3.50 }\n    params.str_wsc   = 0.3\n    params.int_wsc   = 0.3\n    params.atkVaries = { 1.50, 1.50, 1.50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Ground Strike\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.ground_strike.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.50, 1.75, 3.00 }\n    params.str_wsc   = 0.5\n    params.int_wsc   = 0.5\n    params.atkVaries = { 1.75, 1.75, 1.75 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Scourge\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.scourge.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.0, 3.0, 3.0 }\n    params.mnd_wsc = 0.4\n    params.chr_wsc = 0.4\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/hand_to_hand.lua"]={["Path"]="modules/era/lua/actions/weaponskills/hand_to_hand.lua",["SHA256"]="b21d5f8dcf5f4cef39d44dadc94ec707da7655214b414bc902324d001bcf150a",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_hand_to_hand', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Combo\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.combo.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 3\n    params.ftpMod  = { 1.00, 1.50, 2.00 }\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shoulder Tackle\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shoulder_tackle.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.vit_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.HAND_TO_HAND,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(4 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- One Inch Punch\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.one_inch_punch.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params          = {}\n    params.numHits        = 2\n    params.ftpMod         = { 1.00, 1.00, 1.00 }\n    params.vit_wsc        = 0.4\n    params.ignoredDefense = { 0.00, 0.375, 0.75 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Backhand Blow\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.backhand_blow.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    pa