skills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Dragon Kick\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.dragon_kick.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 2.00, 2.75, 3.50 }\n    params.str_wsc = 0.5\n    params.vit_wsc = 0.5\n    params.kick    = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Asuran Fists\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.asuran_fists.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 8\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.str_wsc   = 0.1\n    params.vit_wsc   = 0.1\n    params.accVaries = { 0, 30, 50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Final Heaven\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.final_heaven.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.vit_wsc = 0.6\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Ascetic's Fury\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.ascetics_fury.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 2\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.atkVaries  = { 2.00, 2.00, 2.00 }\n    params.critVaries = { 0.20, 0.40, 0.80 }\n    params.str_wsc    = 0.5\n    params.vit_wsc    = 0.5\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Stringing Pummel\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.stringing_pummel.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 6\n    params.ftpMod     = { 0.75, 0.75, 0.75 }\n    params.str_wsc    = 0.32\n    params.vit_wsc    = 0.32\n    params.critVaries = { 0.10, 0.22, 0.36 }\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/katana.lua"]={["Path"]="modules/era/lua/actions/weaponskills/katana.lua",["SHA256"]="88f9de25b75bde0e4d02bf7bbee6afbdd3ad5d57e108a59e8d39827adb658f41",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_katana', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Blade: Rin\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_rin.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.2\n    params.dex_wsc    = 0.2\n    params.critVaries = { 0.30, 0.63, 0.96 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Retsu\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_retsu.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = utils.clamp(30 + 3 * (player:getMainLvl() - target:getMainLvl()), 5, 35)\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.KATANA,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(xi.weaponskills.fTP(tp, { 30, 60, 120 }) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Teki\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_teki.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 0.50, 0.75, 1.00 }\n    params.str_wsc    = 0.2\n    params.int_wsc    = 0.2\n    params.hybridWS   = true\n    params.ele        = xi.element.WATER\n    params.skill      = xi.skill.KATANA\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: To\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_to.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 0.50, 0.75, 1.00 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.hybridWS   = true\n    params.ele        = xi.element.ICE\n    params.skill      = xi.skill.KATANA\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Chi\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_chi.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 2\n    params.ftpMod     = { 0.50, 0.75, 1.00 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.hybridWS   = true\n    params.ele        = xi.element.EARTH\n    params.skill      = xi.skill.KATANA\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Ei\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_ei.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 1.50, 2.00 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.KATANA\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, false, damage\nend)\n\n-----------------------------------\n-- Blade: Jin\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_jin.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 3\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.3\n    params.dex_wsc    = 0.3\n    params.critVaries = { 0.10, 0.20, 0.40 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Ten\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_ten.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 2.50, 2.75, 3.00 }\n    params.str_wsc = 0.3\n    params.dex_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Ku\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_ku.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 5\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.str_wsc   = 0.1\n    params.dex_wsc   = 0.1\n    params.accVaries = { 0, 30, 50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Metsu\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_metsu.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.dex_wsc = 0.6\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = 10\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.KATANA,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(60 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blade: Kamu\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blade_kamu.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.str_wsc   = 0.5\n    params.int_wsc   = 0.5\n    params.atkVaries = { 1.30, 1.30, 1.30 }\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ACCURACY_DOWN\n    local actionElement = xi.element.EARTH\n    local power         = 10\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.KATANA,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor(6 * tp / 100 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/marksmanship.lua"]={["Path"]="modules/era/lua/actions/weaponskills/marksmanship.lua",["SHA256"]="46a594cc351682090f1fe73ee1f7309c9b10ac8757ed69c0e046914085665f30",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_marksmanship', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Hot Shot\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.hot_shot.onUseWeaponSkill', function(player, target, wsID, tp, primary, action)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 0.50, 0.75, 1.00 }\n    params.agi_wsc    = 0.3\n    params.hybridWS   = true\n    params.ele        = xi.element.FIRE\n    params.skill      = xi.skill.MARKSMANSHIP\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Split Shot\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.split_shot.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 1.00, 1.00, 1.00 }\n    params.agi_wsc             = 0.3\n    params.ignoredDefense      = { 0.00, 0.375, 0.75 }\n    params.rangedAccuracyBonus = 30\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Sniper Shot\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.sniper_shot.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.agi_wsc    = 0.3\n    params.critVaries = { 0.20, 0.50, 1.00 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.INT_DOWN\n    local actionElement = xi.element.FIRE\n    local power         = 10\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.MARKSMANSHIP,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor(140 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Slug Shot\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.slug_shot.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 5.00, 5.00, 5.00 }\n    params.agi_wsc             = 0.3\n    params.rangedAccuracyBonus = math.floor(-25 * xi.weaponskills.fTP(tp, { 2, 1, 0 }))\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Blast Shot\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.blast_shot.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 2.00, 2.00, 2.00 }\n    params.agi_wsc             = 0.3\n    params.rangedAccuracyBonus = math.floor(25 * xi.weaponskills.fTP(tp, { 0, 1, 2 }))\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Heavy Shot\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.heavy_shot.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 3.50, 3.50, 3.50 }\n    params.agi_wsc    = 0.3\n    params.critVaries = { 0.20, 0.50, 0.90 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Detonator\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.detonator.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 1.5, 2.0, 2.5 }\n    params.atkVaries           = { 2.0, 2.0, 2.0 }\n    params.agi_wsc             = 0.3\n    params.rangedAccuracyBonus = 100\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Coronach\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.coronach.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 3.0, 3.0, 3.0 }\n    params.dex_wsc             = 0.4\n    params.agi_wsc             = 0.4\n    params.overrideCE          = 80\n    params.overrideVE          = 240\n    params.rangedAccuracyBonus = 100\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.RELIC)\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Trueflight\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.trueflight.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 4.0, 4.25, 4.75 }\n    params.agi_wsc    = 0.3\n    params.ele        = xi.element.LIGHT\n    params.skill      = xi.skill.MARKSMANSHIP\n    params.includemab = true\n    params.dStat      = xi.mod.AGI\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Leaden Salute\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.leaden_salute.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 4.0, 4.25, 4.75 }\n    params.agi_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.MARKSMANSHIP\n    params.includemab = true\n    params.dStat      = xi.mod.AGI\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/polearm.lua"]={["Path"]="modules/era/lua/actions/weaponskills/polearm.lua",["SHA256"]="9208604a4dd1eaba357cdd357d2a9509cdc134d50f5f0ff10bb8911682eb6869",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_polearm', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Double Thrust\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.double_thrust.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.50, 2.00 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Thunder Thrust\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.thunder_thrust.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.50, 2.00, 2.50 }\n    params.str_wsc    = 0.2\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.THUNDER\n    params.skill      = xi.skill.POLEARM\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Raiden Thrust\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.raiden_thrust.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.00, 3.00 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.THUNDER\n    params.skill      = xi.skill.POLEARM\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Leg Sweep\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.leg_sweep.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.POLEARM,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(4 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Penta Thrust\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.penta_thrust.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 5\n    params.ftpMod    = { 1.00, 1.00, 1.00 }\n    params.str_wsc   = 0.2\n    params.dex_wsc   = 0.2\n    params.accVaries = { 0, 30, 50 } -- TODO: Unknown what 3k used to be, 50 is guessed. This was updated in 2013. 1k may also have been a penalty but that is unverifiable. JP patch notes indicate 1k and 3k anchor points were changed but not 3k\n    params.atkVaries = { 0.875, 0.875, 0.875 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Vorpal Thrust\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.vorpal_thrust.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.2\n    params.agi_wsc    = 0.2\n    params.critVaries = { 0.30, 0.63, 0.96 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Skewer\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.skewer.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 3\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.35\n    params.critVaries = { 0.15, 0.30, 0.50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Wheeling Thrust\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.wheeling_thrust.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params          = {}\n    params.numHits        = 1\n    params.ftpMod         = { 1.75, 1.75, 1.75 }\n    params.str_wsc        = 0.5\n    params.ignoredDefense = { 0.5, 0.625, 0.75 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Impulse Drive\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.impulse_drive.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.50, 2.50 }\n    params.str_wsc = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Geirskogul\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.geirskogul.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.agi_wsc = 0.6\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Drakesbane\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.drakesbane.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 4\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.5\n    params.critVaries = { 0.1, 0.2, 0.3 }\n    params.atkVaries  = { 0.8125, 0.8125, 0.8125 }\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/scythe.lua"]={["Path"]="modules/era/lua/actions/weaponskills/scythe.lua",["SHA256"]="8acff7ea8bb7877059261378cc0dccb821a3aab2f7c507bc01ec31d7f4dacd99",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_scythe', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Slice\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.slice.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.50, 1.75, 2.00 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Dark Harvest\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.dark_harvest.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.00, 2.50 }\n    params.str_wsc    = 0.2\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.SCYTHE\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shadow of Death\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shadow_of_death.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.50, 3.00 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.SCYTHE\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Nightmare Scythe\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.nightmare_scythe.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params    = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.3\n    params.chr_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.BLINDNESS\n    local actionElement = xi.element.DARK\n    local power         = 20\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.SCYTHE,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor((6 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Spinning Scythe\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.spinning_scythe.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Vorpal Scythe\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.vorpal_scythe.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 1\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.35\n    params.critVaries = { 0.30, 0.63, 0.96 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Guillotine\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.guillotine.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 4\n    params.ftpMod  = { 0.875, 0.875, 0.875 }\n    params.str_wsc = 0.25\n    params.mnd_wsc = 0.25\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.SILENCE\n    local actionElement = xi.element.WIND\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.SCYTHE,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor((30 + 3 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Cross Reaper\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.cross_reaper.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 2.0, 2.25, 2.5 }\n    params.str_wsc = 0.3\n    params.int_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Spiral Hell\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.spiral_hell.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.375, 1.875, 3.625 }\n    params.str_wsc = 0.5\n    params.int_wsc = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Catastrophe\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.catastrophe.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    local targetHP = target:getHP()\n    params.numHits = 1\n    params.ftpMod  = { 2.75, 2.75, 2.75 }\n    params.agi_wsc = 0.4\n    params.int_wsc = 0.4\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle HP Drain\n    if not target:isUndead() then\n        local drain = math.floor(damage * math.randomInt(30, 70) / 100)\n\n        drain = utils.clamp(drain, 0, targetHP)\n\n        player:addHP(drain)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Insurgency\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.insurgency.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 4\n    params.ftpMod  = { 0.50, 0.75, 1.00 }\n    params.str_wsc = 0.2\n    params.int_wsc = 0.2\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/staff.lua"]={["Path"]="modules/era/lua/actions/weaponskills/staff.lua",["SHA256"]="d692aabee5cb5c498c3047dee0ceb82a540fa313b8be94de4666c34fef9289b3",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_staff', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Heavy Swing\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.heavy_swing.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.25, 2.25 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Rock Crusher\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.rock_crusher.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.00, 2.50 }\n    params.str_wsc    = 0.2\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.EARTH\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Earth Crusher\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.earth_crusher.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.3125, 3.625 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.EARTH\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Starburst\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.starburst.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.00, 2.50 }\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    params.ele        = xi.element.LIGHT\n    params.dStat      = xi.mod.INT\n\n    if math.randomInt(1, 100) <= 50 then\n        params.ele = xi.element.DARK\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Sunburst\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.sunburst.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.50, 4.00 }\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    params.ele        = xi.element.LIGHT\n    params.dStat      = xi.mod.INT\n\n    if math.randomInt(1, 100) <= 50 then\n        params.ele = xi.element.DARK\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shell Crusher\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shell_crusher.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.35\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.STAFF,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor((120 + 6 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Full Swing\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.full_swing.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params  = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 3.00, 5.00 }\n    params.str_wsc = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Spirit Taker\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.spirit_taker.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.50, 2.00 }\n    params.int_wsc = 0.5\n    params.mnd_wsc = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    player:addMP(damage)\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Retribution\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.retribution.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 2.00, 2.50, 3.00 }\n    params.atkVaries = { 1.50, 1.50, 1.50 }\n    params.str_wsc   = 0.3\n    params.mnd_wsc   = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Gate of Tartarus\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.gate_of_tartarus.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.chr_wsc = 0.6\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ATTACK_DOWN\n    local actionElement = xi.element.WATER\n    local power         = 18.75\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.STAFF,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor(120 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Vidohunir\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.vidohunir.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.75, 1.75, 1.75 }\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    -- params.dStat = xi.mod.INT\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.MAGIC_DEF_DOWN\n    local actionElement = xi.element.THUNDER\n    local power         = 10\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.STAFF,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor(6 * tp / 100 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Garland of Bliss\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.garland_of_bliss.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod     = { 2.25, 2.25, 2.25 }\n    params.str_wsc    = 0.3\n    params.mnd_wsc    = 0.3\n    params.ele        = xi.element.LIGHT\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n     -- params.dStat = xi.mod.MND\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 12.5\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.STAFF,\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor((6 * tp / 100) * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["modules/era/lua/actions/weaponskills/sword.lua"]={["Path"]="modules/era/lua/actions/weaponskills/sword.lua",["SHA256"]="1a210625901b39455d69894270bd8ab4f4581be8009a5a25259905c4b2e650a6",["Text"]="-----------------------------------\n-- Date : 2007-11-19 (One day prior to WoTG release)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\n\nlocal m = Module:new('toau_sword', xi.pre(xi.expansion.WOTG))\n\n-----------------------------------\n-- Fast Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.fast_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.50, 2.00 }\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Burning Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.burning_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.00, 2.50 }\n    params.str_wsc    = 0.2\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.FIRE\n    params.skill      = xi.skill.SWORD\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Red Lotus Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.red_lotus_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.375, 3.00 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.2\n    params.ele        = xi.element.FIRE\n    params.skill      = xi.skill.SWORD\n    params.includemab = true\n    params.dStat      = xi.mod.INT\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Flat Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.flat_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.SWORD,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 0) then\n        local duration = math.floor(4 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Shining Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.shining_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits    = 1\n    params.ftpMod     = { 1.00, 2.00, 2.50 }\n    params.str_wsc    = 0.2\n    params.mnd_wsc    = 0.2\n    params.ele        = xi.element.LIGHT\n    params.skill      = xi.skill.SWORD\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Seraph Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.seraph_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.00, 2.50, 3.00 }\n    params.str_wsc    = 0.3\n    params.mnd_wsc    = 0.3\n    params.ele        = xi.element.LIGHT\n    params.skill      = xi.skill.SWORD\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Circle Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.circle_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.00, 1.00, 1.00 }\n    params.str_wsc = 0.35\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Spirits Within\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.spirits_within.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.ftpMod  = { 0.0625, 0.1875, 0.46875 }\n\n    local attack =\n    {\n        ['type'] = xi.attackType.BREATH,\n        ['slot'] = xi.slot.MAIN,\n        ['weaponType'] = player:getWeaponSkillType(xi.slot.MAIN),\n        ['damageType'] = xi.damageType.ELEMENTAL\n    }\n\n    local calcParams =\n    {\n        wsID = wsID,\n        criticalHit     = false,\n        hitsLanded      = 1,\n        tpHitsLanded    = 0,\n        extraHitsLanded = 0,\n        shadowsAbsorbed = 0,\n        bonusTP         = 0\n    }\n\n    local playerHP = player:getHP()\n    local dmg = 0\n\n    local ftp = xi.weaponskills.fTP(tp, params.ftpMod)\n    dmg = math.floor(playerHP * ftp)\n\n    local damage = dmg\n    damage = math.floor(damage * xi.combat.damage.calculateDamageAdjustment(target, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateAbsorption(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateNullification(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(target:handleSevereDamage(damage, false))\n\n    if damage > 0 then\n        if player:getOffhandDmg() > 0 then\n            calcParams.tpHitsLanded = 2\n        else\n            calcParams.tpHitsLanded = 1\n        end\n    end\n\n    if player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID) > 0 then\n        damage = damage * (100 + player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID)) / 100\n    end\n\n    damage = damage * xi.settings.main.WEAPON_SKILL_POWER\n    calcParams.finalDmg = damage\n\n    -- Todo: xi.weaponskills.doBreathWeaponskill() instead of all this.\n    damage = xi.weaponskills.takeWeaponskillDamage(target, player, {}, primary, attack, calcParams, action)\n\n    return calcParams.tpHitsLanded, calcParams.extraHitsLanded, calcParams.criticalHit, damage\nend)\n\n-----------------------------------\n-- Vorpal Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.vorpal_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 4\n    params.ftpMod     = { 1.00, 1.00, 1.00 }\n    params.str_wsc    = 0.3\n    params.critVaries = { 0.15, 0.30, 0.50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Swift Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.swift_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 3\n    params.ftpMod    = { 1.50, 1.50, 1.50 }\n    params.str_wsc   = 0.3\n    params.mnd_wsc   = 0.3\n    params.accVaries = { 0, 30, 50 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Savage Blade\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.savage_blade.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.75, 3.50 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Knights of Round\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.knights_of_round.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.00, 3.00, 3.00 }\n    params.str_wsc = 0.4\n    params.mnd_wsc = 0.4\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Atonement\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.atonement.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.00, 1.50, 2.00 }\n\n    -- 1000 TP: 9% CE + 11% VE, 2000 TP: 11% CE + 14% VE, 3000 TP: 20% CE + 25% VE\n    local cePercent = xi.weaponskills.fTP(tp, { 0.09, 0.11, 0.20 })\n    local vePercent = xi.weaponskills.fTP(tp, { 0.11, 0.14, 0.25 })\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local attack =\n    {\n        ['type'] = xi.attackType.BREATH,\n        ['slot'] = xi.slot.MAIN,\n        ['weaponType'] = player:getWeaponSkillType(xi.slot.MAIN),\n        ['damageType'] = xi.damageType.ELEMENTAL\n    }\n\n    local calcParams =\n    {\n        wsID            = wsID,\n        criticalHit     = false,\n        hitsLanded      = 1,\n        tpHitsLanded    = 0,\n        extraHitsLanded = 0,\n        shadowsAbsorbed = 0,\n        bonusTP         = 0\n    }\n\n    local damage = 0\n\n    local levelUsed       = player:getMainLvl()\n    local globalDamageCap = levelUsed * 10 -- 750 at level 75.\n\n    -- If the target isn't a mob,theres no enmity to calculate with.\n    if target:getObjType() ~= xi.objType.MOB then\n        params.ftpMod = { 1.00, 1.50, 2.00 }\n\n        damage, calcParams.criticalHit, calcParams.tpHitsLanded, calcParams.extraHitsLanded = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n        return calcParams.tpHitsLanded, calcParams.extraHitsLanded, calcParams.criticalHit, damage\n    end\n\n    -- Calculate damage based on target's CE and VE, clamped to the global damage cap.\n    damage = utils.clamp(target:getCE(player) * cePercent + target:getVE(player) * vePercent, 0, globalDamageCap)\n\n    -- This is here to account for damage adjustments needed because it is breath damage.\n    damage = math.floor(damage * xi.combat.damage.calculateDamageAdjustment(target, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateAbsorption(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateNullification(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(target:handleSevereDamage(damage, false))\n\n    if player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID) > 0 then\n        damage = damage * (100 + player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID)) / 100\n    end\n\n    calcParams.finalDmg = damage\n\n    -- If one or more hits land, Atonement always counts as landing both hits.\n    if damage > 0 then\n        if player:getOffhandDmg() > 0 then\n            calcParams.tpHitsLanded = 2\n        else\n            calcParams.tpHitsLanded = 1\n        end\n\n        -- Atonement always yields the a TP return of a 2 hit WS (unless it does 0 damage), because if one hit lands, both hits do.\n        calcParams.extraHitsLanded = 1\n    end\n\n    damage = xi.weaponskills.takeWeaponskillDamage(target, player, params, primary, attack, calcParams, action)\n\n    -- If Atonement deals 0 damage, it will print as 0 damage instead of a miss.\n    if damage == 0 then\n        action:resolution(target:getID(), xi.action.resolution.HIT)\n        action:messageID(target:getID(), xi.msg.basic.DAMAGE)\n    end\n\n    return calcParams.tpHitsLanded, calcParams.extraHitsLanded, calcParams.criticalHit, damage\nend)\n\n-----------------------------------\n-- Death Blossom\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.death_blossom.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 3\n    params.ftpMod  = { 1.125, 1.125, 1.125 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.5\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.MAGIC_EVASION_DOWN\n    local actionElement = xi.element.THUNDER\n    local power         = 10\n    local maccParams    =\n    {\n        effectId       = effectId,\n        magicalElement = actionElement,\n        skillType      = xi.skill.SWORD,\n        bonusMacc      = xi.weaponskills.fTP(tp, { 25, 50, 100 }),\n    }\n\n    local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n    if xi.data.statusEffect.isResistRateSuccessfull(effectId, resistanceRate, 1) then\n        local duration = math.floor(60 * resistanceRate)\n\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend)\n\n-----------------------------------\n-- Expiacion\n-----------------------------------\nm:addOverride('xi.actions.weaponskills.expiacion.onUseWeaponSkill', function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1.50, 2.00, 2.50 }\n    params.str_wsc = 0.3\n    params.int_wsc = 0.3\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend)\n"},["scripts/actions/weaponskills/aeolian_edge.lua"]={["Path"]="scripts/actions/weaponskills/aeolian_edge.lua",["SHA256"]="9b7385962f9c0b81a618b435dceb11c176916f6b82a490ecfdd1b48fa223370a",["Text"]="-- Aeolian Edge\n-- Dagger weapon skill\n-- Delivers an area attack that deals wind elemental damage. Damage varies with TP.\n-- Skill Level: 290\n-- Aligned with the Breeze Gorget, Soil Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt, Soil Belt & Thunder Belt.\n-- Element: Wind\n-- Skillchain Properties: Impaction / Scission / Detonation\n-- Modifiers: DEX:28% INT:28%\n-- 100%TP    200%TP    300%TP\n-- 2.75      3.50       4\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 2.75, 3.5, 4 }\n    params.dex_wsc = 0.28 params.int_wsc = 0.28\n    params.ele = xi.element.WIND\n    params.skill = xi.skill.DAGGER\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        -- https://www.bg-wiki.com/bg/Aeolian_Edge\n        params.ftpMod = { 2, 3, 4.5 }\n        params.dex_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/apex_arrow.lua"]={["Path"]="scripts/actions/weaponskills/apex_arrow.lua",["SHA256"]="ad9d69757322b2d0ae9a9dfdd3a3eeee61797132008c1d9a0c3a9567ff031dac",["Text"]="-----------------------------------\n-- Apex Arrow\n-- Archery weapon skill\n-- Skill level: 357\n-- Merit\n-- RNG or SAM\n-- Aligned with the Thunder & Light Gorget.\n-- Aligned with the Thunder Belt & Light Belt.\n-- Element: None\n-- Modifiers: AGI:73~85%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3, 3, 3 }\n    params.agi_wsc = player:getMerit(xi.merit.APEX_ARROW) * 0.17\n    params.ignoredDefense = { 0.15, 0.35, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.7 + (player:getMerit(xi.merit.APEX_ARROW) * 0.03)\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/arching_arrow.lua"]={["Path"]="scripts/actions/weaponskills/arching_arrow.lua",["SHA256"]="4b24d3e4eb2543e13eed1ef012c5cca670e2eab1525b4ebaa07f5303a20457db",["Text"]="-----------------------------------\n-- Arching Arrow\n-- Archery weapon skill\n-- Skill level: 225\n-- Delivers a single-hit attack. Chance of params.critical varies with TP.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:16%  AGI:25%\n-- 100%TP    200%TP    300%TP\n-- 3.50      3.50      3.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.5, 3.5, 3.5 }\n    params.str_wsc = 0.16 params.agi_wsc = 0.25\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.20 params.agi_wsc = 0.50\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/armor_break.lua"]={["Path"]="scripts/actions/weaponskills/armor_break.lua",["SHA256"]="ac7dffa04d64c60ad75ed421a770e88121347576bd309e43a1a003883a09aa22",["Text"]="-----------------------------------\n-- Armor Break\n-- Great Axe weapon skill\n-- Skill level: 100\n-- Lowers enemy's defense. Duration of effect varies with TP.\n-- Lowers defense by as much as 25% if unresisted.\n-- Strong against: Antica, Bats, Cockatrice, Dhalmel, Lizards, Mandragora, Worms.\n-- Immune: Ahriman.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: Wind\n-- Modifiers: STR:20%  VIT:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.2\n    params.vit_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n        params.vit_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local duration      = math.floor((120 + 6 * tp / 100) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/ascetics_fury.lua"]={["Path"]="scripts/actions/weaponskills/ascetics_fury.lua",["SHA256"]="27eb0f2818c50db693573a14452b8d3d1c1f0127ba42c0193b909a908cfe1351",["Text"]="-----------------------------------\n-- Ascetics Fury\n-- Hand-to-Hand weapon skill\n-- Skill Level: N/A\n-- Chance of params.critical hit varies with TP. Glanzfaust: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Monk) quest.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:50%  VIT:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 2\n    params.ftpMod     = { 1, 1, 1 }\n    params.atkVaries  = { 1.5, 1.5, 1.5 } -- https://w.atwiki.jp/studiogobli/pages/93.html\n    params.critVaries = { 0.1, 0.2, 0.4 }\n    params.str_wsc    = 0.5\n    params.vit_wsc    = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/15880.html\n        params.critVaries  = { 0.2, 0.3, 0.5 }\n        params.atkVaries   = { 2.5, 2.5, 2.5 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/asuran_fists.lua"]={["Path"]="scripts/actions/weaponskills/asuran_fists.lua",["SHA256"]="fbda85a505f15654b0f7e124b658bceb5aa9decd890bd195628fe1f1420070e3",["Text"]="-----------------------------------\n-- Asuran Fists\n-- Hand-to-Hand weapon skill\n-- Skill Level: 250\n-- Delivers an eightfold attack. params.accuracy varies with TP.\n-- In order to obtain Asuran Fists, the quest The Walls of Your Mind must be completed.\n-- Due to the 95% params.accuracy cap there is only a 66% chance of all 8 hits landing, so approximately a one third chance of missing some of the hits at the cap.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Soil Gorget & Flame Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Flame Belt.\n-- Element: None\n-- Modifiers: STR:10%  VIT:10%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 8\n    params.ftpMod = { 1, 1, 1 }\n    params.str_wsc = 0.1 params.vit_wsc = 0.1\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2424.html\n        params.str_wsc = 0.15 params.vit_wsc = 0.15\n        params.ftpMod = { 1.25, 1.25, 1.25 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/atonement.lua"]={["Path"]="scripts/actions/weaponskills/atonement.lua",["SHA256"]="a8bc813bc4efafaf1ca837e9c8a09a990ca850dd4ccb2d5d3d78b4799608ca10",["Text"]="-----------------------------------\n-- Atonement\n-- TODO: This needs to be reworked, as this weapon skill does damage based on current enmity, not based on stat modifiers. http://wiki.ffxiclopedia.org/wiki/Atonement    http://www.bg-wiki.com/bg/Atonement\n-- Sword weapon skill\n-- Skill Level: N/A\n-- Delivers a Twofold attack. Enmity varies with TP. Burtgang: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Paladin) quest.\n-- Aligned with the Aqua Gorget, Flame Gorget & Light Gorget.\n-- Aligned with the Aqua Belt, Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers (old): damage varies with enmity\n-- 100%TP    200%TP    300%TP\n-- 0.09      0.11      0.20   -CE\n-- 0.11      0.14      0.25   -VE\n-- Modifiers (new): enmity from damage varies with TP\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.5       2.0\n-- Modifiers (non-mob, wrong): STR:40% VIT:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.25      1.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits    = 2\n    params.ftpMod     = { 1, 1.25, 1.5 }\n    params.str_wsc    = 0.4\n    params.vit_wsc    = 0.5\n    params.enmityMult = 1\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local attack =\n    {\n        ['type'] = xi.attackType.BREATH,\n        ['slot'] = xi.slot.MAIN,\n        ['weaponType'] = player:getWeaponSkillType(xi.slot.MAIN),\n        ['damageType'] = xi.damageType.ELEMENTAL\n    }\n    local calcParams =\n    {\n        wsID            = wsID,\n        criticalHit     = false,\n        hitsLanded      = 1,\n        tpHitsLanded    = 0,\n        extraHitsLanded = 0,\n        shadowsAbsorbed = 0,\n        bonusTP         = 0\n    }\n\n    local damage = 0\n\n    -- Calculate damage caps (item level and level based)\n    local levelUsed       = player:getAverageItemLevel() > 99 and player:getAverageItemLevel() or player:getMainLvl()\n    -- local hitDamageCap    = (levelUsed + 14) * 5 -- iLvl 119 -> 665\n    local globalDamageCap = levelUsed * 10       -- iLvl 119 -> 1190\n\n    -- If the target isn't a mob,theres no enmity to calculate with.\n    if target:getObjType() ~= xi.objType.MOB then\n        params.ftpMod = { 1, 1.5, 2 }\n\n        damage, calcParams.criticalHit, calcParams.tpHitsLanded, calcParams.extraHitsLanded = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n        return calcParams.tpHitsLanded, calcParams.extraHitsLanded, calcParams.criticalHit, damage\n    end\n\n    -- Calculate damage based on target's CE and VE, clamped to the global damage cap.\n    damage = utils.clamp((target:getCE(player) + target:getVE(player)) / 6, 0, globalDamageCap)\n\n    -- TP affects enmity multiplier, 1.0 at 1k, 1.5 at 2k, 2.0 at 3k. Gorget/Belt adds 100 tp each.\n    params.enmityMult = params.enmityMult + (tp + xi.combat.physical.calculateFTPBonus(player) * 1000 - 1000) / 2000\n    params.enmityMult = utils.clamp(params.enmityMult, 1, 2) -- necessary because of Gorget/Belt bonus\n\n    damage = math.floor(damage * xi.combat.damage.calculateDamageAdjustment(target, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateAbsorption(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateNullification(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(target:handleSevereDamage(damage, false))\n\n    if player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID) > 0 then\n        damage = damage * (100 + player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID)) / 100\n    end\n\n    calcParams.finalDmg = damage\n\n    if damage > 0 then\n        if player:getOffhandDmg() > 0 then\n            calcParams.tpHitsLanded = 2\n        else\n            calcParams.tpHitsLanded = 1\n        end\n\n        -- Atonement always yields the a TP return of a 2 hit WS (unless it does 0 damage), because if one hit lands, both hits do.\n        calcParams.extraHitsLanded = 1\n    end\n\n    damage = xi.weaponskills.takeWeaponskillDamage(target, player, params, primary, attack, calcParams, action)\n\n    if damage == 0 then\n        -- The logic above sets the action as a miss if CE/VE are 0 on the target\n        -- because the landed hits are (correctly) set to 0\n        -- Atonement is not known to miss and should always report as a hit.\n        -- It is fairly unique in that regard, which is why it is handled as a special case here.\n        action:resolution(target:getID(), xi.action.resolution.HIT)\n        action:messageID(target:getID(), xi.msg.basic.DAMAGE)\n    end\n\n    return calcParams.tpHitsLanded, calcParams.extraHitsLanded, calcParams.criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/avalanche_axe.lua"]={["Path"]="scripts/actions/weaponskills/avalanche_axe.lua",["SHA256"]="bf615567129fdcecbe0e911c1644dfb53a328731fba53727c49b65bdcc00366c",["Text"]="-----------------------------------\n-- Avalanche Axe\n-- Axe weapon skill\n-- Skill level: 100\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget & Thunder Gorget.\n-- Aligned with the Soil Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.50      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.5, 2, 2.5 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/backhand_blow.lua"]={["Path"]="scripts/actions/weaponskills/backhand_blow.lua",["SHA256"]="1726ef6fc68c33ffebdb5bae2e891b7061f230e87c48b71d136352f2afe85572",["Text"]="-----------------------------------\n-- Backhand Blow\n-- Hand-to-Hand weapon skill\n-- Skill Level: 100\n-- Deals params.critical damage. Chance of params.critical hit varies with TP.\n-- Aligned with the Breeze Gorget.\n-- Aligned with the Breeze Belt.\n-- Element: None\n-- Modifiers: STR:30%  DEX:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1, 1, 1 }\n    params.str_wsc = 0.3 params.dex_wsc = 0.3\n    params.critVaries = { 0.4, 0.6, 0.8 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2419.html\n        params.str_wsc = 0.5 params.dex_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/black_halo.lua"]={["Path"]="scripts/actions/weaponskills/black_halo.lua",["SHA256"]="67e8fa57fbdbc37781cd26df951afd40764ab76e0f622d9cafb380d40b090320",["Text"]="-----------------------------------\n-- Black Halo\n-- Club weapon skill\n-- Skill level: 230\n-- In order to obtain Black Halo, the quest Orastery Woes must be completed.\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Thunder Gorget & Breeze Gorget.\n-- Aligned with the Shadow Belt, Thunder Belt & Breeze Belt.\n-- Element: None\n-- Modifiers: STR:30%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- 1.50      2.50      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.5, 2.5, 3 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.0, 7.25, 9.75 }\n        params.mnd_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_chi.lua"]={["Path"]="scripts/actions/weaponskills/blade_chi.lua",["SHA256"]="05c8bab90fe19b62c87745bf29f403e9142c0ea2f8ecb4c2da5d75cafba58ca7",["Text"]="-----------------------------------\n-- Blade Chi\n-- Katana weapon skill\n-- Skill Level: 150\n-- Delivers a two-hit earth elemental attack. Damage varies with TP.\n-- Aligned with the Thunder Gorget & Light Gorget.\n-- Aligned with the Thunder Belt & Light Belt.\n-- Element: Earth\n-- Modifiers: STR:30%  INT:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 0.5, 0.75, 1.0 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.hybridWS = true\n    params.ele = xi.element.EARTH\n    params.skill = xi.skill.KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        -- http://wiki.ffo.jp/html/720.html\n        params.ftpMod = { 0.5, 1.375, 2.25 }\n        params.str_wsc = 0.3 params.int_wsc = 0.3\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_ei.lua"]={["Path"]="scripts/actions/weaponskills/blade_ei.lua",["SHA256"]="39a12cabadf72e656c2b32608fac9bfd715fb5622ad26ddce656d15c9e839ece",["Text"]="-----------------------------------\n-- Blade Ei\n-- Katana weapon skill\n-- Skill Level: 175\n-- Delivers a dark elemental attack. Damage varies with TP.\n-- Aligned with the Shadow Gorget.\n-- Aligned with the Shadow Belt.\n-- Element: Dark\n-- Modifiers: STR:30%  INT:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n    params.ele = xi.element.DARK\n    params.skill = xi.skill.KATANA\n    params.includemab = true\n\n    -- to do ignore shadow and blink https://www.bg-wiki.com/ffxi/Blade:_Ei\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n        params.ftpMod = { 1.0, 3.0, 5.0 }\n    end\n\n    local damage, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, false, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_hi.lua"]={["Path"]="scripts/actions/weaponskills/blade_hi.lua",["SHA256"]="c60421aa3b6c81def33d89a474655fc0e2c8e37ea4c04840d8964af2ade23e8f",["Text"]="-----------------------------------\n-- Blade Hi\n-- Katana weapon skill\n-- Skill level: N/A\n-- Description: Deals quadruple damage. Chance of params.critical hit varies with TP. Kannagi: Aftermath.\n-- Available only when equipped with Kannagi (85)/(90)/(95)/(99) or Tobi +1/+2/+3.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: AGI:60%\n-- Skillchain Properties: Darkness/Gravitation\n-- 100%TP    200%TP    300%TP\n-- 4.00      4.00      4.00\n-----------------------------------\n-- params.critical Hit Rate by TP:\n-- 100%TP    200%TP    300%TP\n-- 15%         20%       25%\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 4.0, 4.0, 4.0 }\n    params.agi_wsc = 0.6\n    params.critVaries = { 0.15, 0.20, 0.25 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 5.0, 5.0, 5.0 }\n        params.agi_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_jin.lua"]={["Path"]="scripts/actions/weaponskills/blade_jin.lua",["SHA256"]="eb78f6b0a9eab090de3ba2488cf5ec37544c1ff8b351202c8aff2b5074bc61b4",["Text"]="-----------------------------------\n-- Blade Jin\n-- Katana weapon skill\n-- Skill Level: 200\n-- Delivers a three-hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: Wind\n-- Modifiers: STR:30%  DEX:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3 params.dex_wsc = 0.3\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.375, 1.375, 1.375 }\n        params.multiHitfTP = true -- https://www.bg-wiki.com/ffxi/Blade:_Jin\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_kamu.lua"]={["Path"]="scripts/actions/weaponskills/blade_kamu.lua",["SHA256"]="cc4b456e0ae5a44127f456abef856f3c0802c6188eced6e6a74b5329d172374d",["Text"]="-----------------------------------\n-- Blade Kamu\n-- Katana weapon skill\n-- Skill Level: N/A\n-- Lowers target's params.accuracy. Duration of effect varies with TP. Nagi: Aftermath effect varies with TP.\n-- Effect lasts 60 seconds @ 100 TP, 90 seconds @ 200 TP, and 120 seconds @ 300 TP\n-- Available only after completing the Unlocking a Myth (Ninja) quest.\n-- Aligned with the Shadow Gorget, Thunder Gorget & Breeze Gorget.\n-- Aligned with the Shadow Belt, Thunder Belt & Breeze Belt.\n-- Element: None\n-- Modifiers: STR:50%  INT:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1, 1, 1 }\n    params.str_wsc   = 0.5\n    params.int_wsc   = 0.5\n    params.atkVaries = { 1.3, 1.3, 1.3 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc        = 0.6\n        params.int_wsc        = 0.6\n        params.ignoredDefense = { 0.25, 0.25, 0.25 }\n        params.atkVaries      = { 2.25, 2.25, 2.25 } -- http://wiki.ffo.jp/html/15893.html\n    end\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ACCURACY_DOWN\n    local actionElement = xi.element.EARTH\n    local power         = 10\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_ku.lua"]={["Path"]="scripts/actions/weaponskills/blade_ku.lua",["SHA256"]="4619003ccf1d4703f6ea91d3dd832d1403721c0d90ee68c4a65410a16f745271",["Text"]="-----------------------------------\n-- Blade Ku\n-- Katana weapon skill\n-- Skill level: N/A\n-- Description: Delivers a five-hit attack. params.accuracy varies with TP.\n-- In order to obtain Blade: Ku, the quest Bugi Soden must be completed.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Soil Gorget & Light Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Light Belt.\n-- Skillchain Properties: Gravitation/Transfixion\n-- Modifiers: STR:10%  DEX:10%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n--         params.acc\n-- 100%TP    200%TP    300%TP\n-- ??        ??        ??\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.1 params.dex_wsc = 0.1\n    -- Sufficient data for ACC bonus/penalty does not exist; assuming no penalty and 10% increase per 1000 TP\n    -- http://wiki.ffo.jp/html/732.html does not list ACC Bonus\n    -- https://www.bg-wiki.com/ffxi/Blade:_Ku does not list ACC Bonus\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.25, 1.25, 1.25 }\n        params.str_wsc = 0.3 params.dex_wsc = 0.3\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_metsu.lua"]={["Path"]="scripts/actions/weaponskills/blade_metsu.lua",["SHA256"]="ff5f1526143be37420b15cedcd89bf084323f3628a50f89ae847ef755e2fa8a2",["Text"]="-----------------------------------\n-- Blade Metsu\n-- Katana weapon skill\n-- Skill Level: N/A\n-- Additional effect: Paralysis\n-- Hidden effect: temporarily enhances Subtle Blow xi.effect.\n-- One hit weapon skill, despite non single-hit animation.\n-- This weapon skill is only available with the stage 5 relic Katana Kikoku or within Dynamis with the stage 4 Yoshimitsu.\n-- Weaponskill is also available with the Sekirei Katana obtained from Abyssea NM Sedna.\n-- Aligned with the Shadow Gorget, Breeze Gorget & Thunder Gorget.\n-- Aligned with the Shadow Belt, Breeze Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: DEX:60%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3, 3, 3 }\n    params.dex_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 5, 5, 5 }\n        params.dex_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = 10\n    local duration      = math.floor(60 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_retsu.lua"]={["Path"]="scripts/actions/weaponskills/blade_retsu.lua",["SHA256"]="24519a21ba0e9098732f9c3ad4f5b2e32d8ed0ee3eae3ebd1cdf22c895a03a37",["Text"]="-----------------------------------\n-- Blade Retsu\n-- Katana weapon skill\n-- Skill Level: 30\n-- Delivers a two-hit attack. Paralyzes enemy. Duration of paralysis varies with TP.\n-- Proc rate of Paralyze seems to be based on your level in comparison to the targets level. The higher level you are compared to your target, it will be Paralyzed more often.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = utils.clamp(30 + 3 * (player:getMainLvl() - target:getMainLvl()), 5, 35)\n    local duration      = math.floor(xi.weaponskills.fTP(tp, { 30, 60, 120 }) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"}};
